tools.schema:
{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "question" : {
      "type" : "string",
      "description" : "需要用户澄清的一个问题"
    },
    "options" : {
      "type" : "array",
      "items" : {
        "type" : "object",
        "properties" : {
          "description" : {
            "type" : "string"
          },
          "label" : {
            "type" : "string"
          }
        },
        "required" : [ "description", "label" ],
        "additionalProperties" : false
      },
      "description" : "0到4个选项，label为选项名，description说明选择的影响"
    }
  },
  "required" : [ "question" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "seq" : {
      "type" : "integer",
      "description" : "步骤序号（从 1 开始）"
    },
    "summary" : {
      "type" : "string",
      "description" : "这一步的结论或产出；本步没有调用工具时必填"
    }
  },
  "required" : [ "seq" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "title" : {
      "type" : "string",
      "description" : "日程标题，1~200 字"
    },
    "startsAt" : {
      "type" : "string",
      "description" : "开始时间，ISO-8601，例如 2026-10-15T15:00:00Z 或 2026-10-15"
    },
    "endsAt" : {
      "type" : "string",
      "description" : "结束时间，ISO-8601，不得早于开始时间"
    },
    "location" : {
      "type" : "string",
      "description" : "地点，可省略"
    },
    "description" : {
      "type" : "string",
      "description" : "描述，可省略"
    },
    "allDay" : {
      "type" : "boolean",
      "description" : "是否全天日程，默认 false；为 true 时起止时间会被归一化到当天"
    },
    "recurrenceType" : {
      "type" : "string",
      "description" : "重复类型：NONE（默认）/ DAILY / WEEKLY / MONTHLY / WEEKDAYS"
    },
    "recurrenceUntil" : {
      "type" : "string",
      "description" : "重复截止时间，ISO-8601；省略表示无限重复"
    },
    "reminderLeadMinutes" : {
      "type" : "integer",
      "description" : "提前多少分钟提醒，默认 15，最大 10080"
    }
  },
  "required" : [ "title", "startsAt", "endsAt" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "goal" : {
      "type" : "string",
      "description" : "目标的一句话复述，例如：把本周所有未完成任务按优先级重排"
    },
    "steps" : {
      "type" : "array",
      "items" : {
        "type" : "string"
      },
      "description" : "有序的步骤标题列表，2~12 步。每步应是一个可验证的动作，例如 [\"查询未完成任务\", \"按截止时间排序\", \"更新优先级\"]"
    }
  },
  "required" : [ "goal", "steps" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "title" : {
      "type" : "string",
      "description" : "任务标题，1~200 字，例如：交周报"
    },
    "description" : {
      "type" : "string",
      "description" : "任务描述，可省略"
    },
    "priority" : {
      "type" : "string",
      "description" : "优先级，取值 LOW / MEDIUM / HIGH，省略则默认 MEDIUM"
    },
    "dueAt" : {
      "type" : "string",
      "description" : "截止时间，ISO-8601，例如 2026-10-17T10:00:00Z 或 2026-10-17，可省略"
    },
    "tags" : {
      "type" : "array",
      "items" : {
        "type" : "string"
      },
      "description" : "标签，最多 5 个，例如 [\"工作\",\"本周\"]，可省略"
    }
  },
  "required" : [ "title" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "eventIds" : {
      "type" : "array",
      "items" : {
        "type" : "string"
      },
      "description" : "要删除的日程 id 列表，1~50 个。可先调用 findCalendarEvents 获取 id。"
    }
  },
  "required" : [ "eventIds" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "taskIds" : {
      "type" : "array",
      "items" : {
        "type" : "string"
      },
      "description" : "要删除的任务 id 列表，1~50 个。可先调用 findTasks 获取 id。"
    }
  },
  "required" : [ "taskIds" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "seq" : {
      "type" : "integer",
      "description" : "步骤序号（从 1 开始）"
    },
    "reason" : {
      "type" : "string",
      "description" : "失败原因，例如：任务不存在 / 缺少必要参数 / 权限不足"
    }
  },
  "required" : [ "seq", "reason" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "from" : {
      "type" : "string",
      "description" : "区间起点，ISO-8601；省略表示从今天 00:00 开始"
    },
    "to" : {
      "type" : "string",
      "description" : "区间终点，ISO-8601；省略表示起点之后 7 天"
    },
    "limit" : {
      "type" : "integer",
      "description" : "返回条数上限，默认 100，最大 500"
    }
  },
  "required" : [ ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "limit" : {
      "type" : "integer",
      "description" : "返回条数上限，默认 50"
    }
  },
  "required" : [ ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "keyword" : {
      "type" : "string",
      "description" : "关键词，匹配标题或描述，可省略"
    },
    "status" : {
      "type" : "string",
      "description" : "状态筛选：TODO / DOING / DONE，可省略"
    },
    "tag" : {
      "type" : "string",
      "description" : "标签精确筛选，例如「工作」，可省略"
    },
    "limit" : {
      "type" : "integer",
      "description" : "返回条数上限，默认 20，最大 50"
    }
  },
  "required" : [ ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "taskId" : {
      "type" : "string",
      "description" : "任务 id"
    }
  },
  "required" : [ "taskId" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "reminderId" : {
      "type" : "string",
      "description" : "提醒 id"
    }
  },
  "required" : [ "reminderId" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "reason" : {
      "type" : "string",
      "description" : "为什么要换路线，例如：任务接口不可用，改为先导出再处理"
    },
    "steps" : {
      "type" : "array",
      "items" : {
        "type" : "string"
      },
      "description" : "新的步骤标题列表，2~12 步"
    },
    "goal" : {
      "type" : "string",
      "description" : "新的目标复述；省略则沿用原目标"
    }
  },
  "required" : [ "reason", "steps" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "content" : {
      "type" : "string",
      "description" : "要长期记住的内容，1~2000 字，写成一句完整、自足的陈述"
    }
  },
  "required" : [ "content" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "taskId" : {
      "type" : "string",
      "description" : "任务 id"
    },
    "dueAt" : {
      "type" : "string",
      "description" : "新的截止时间，ISO-8601；省略或留空表示清除截止时间"
    }
  },
  "required" : [ "taskId" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "query" : {
      "type" : "string",
      "description" : "检索词或问题的关键词，1~500 字"
    },
    "topK" : {
      "type" : "integer",
      "description" : "返回条数，默认 4，上限 20"
    }
  },
  "required" : [ "query" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "taskId" : {
      "type" : "string",
      "description" : "任务 id"
    },
    "completed" : {
      "type" : "boolean",
      "description" : "true 表示标记完成，false 表示恢复"
    }
  },
  "required" : [ "taskId", "completed" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "taskId" : {
      "type" : "string",
      "description" : "任务 id"
    },
    "priority" : {
      "type" : "string",
      "description" : "新的优先级，取值 LOW / MEDIUM / HIGH"
    }
  },
  "required" : [ "taskId", "priority" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "seq" : {
      "type" : "integer",
      "description" : "步骤序号（从 1 开始）"
    },
    "reason" : {
      "type" : "string",
      "description" : "跳过原因，可省略"
    }
  },
  "required" : [ "seq" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "seq" : {
      "type" : "integer",
      "description" : "步骤序号（从 1 开始）"
    }
  },
  "required" : [ "seq" ],
  "additionalProperties" : false
}

{
  "$schema" : "https://json-schema.org/draft/2020-12/schema",
  "type" : "object",
  "properties" : {
    "taskId" : {
      "type" : "string",
      "description" : "任务 id"
    },
    "title" : {
      "type" : "string",
      "description" : "新的标题，可省略"
    },
    "description" : {
      "type" : "string",
      "description" : "新的描述，可省略"
    },
    "tags" : {
      "type" : "array",
      "items" : {
        "type" : "string"
      },
      "description" : "新的标签列表（整体替换，最多 5 个），可省略；传空数组表示清空"
    }
  },
  "required" : [ "taskId" ],
  "additionalProperties" : false
}
